<?php declare(strict_types=1); namespace Modules\Users\Controllers; use App\Http\Controllers\Controller; use Core\Http\Request; use Core\Http\Response; use Modules\Permissions\Repositories\RoleRepository; use Modules\Users\Requests\StoreUserRequest; use Modules\Users\Requests\UpdateUserRequest; use Modules\Users\Services\UserService; class UserController extends Controller { public function __construct( private readonly UserService $users, private readonly RoleRepository $roles, ) { } public function index(Request $request): Response { $page = (int) $request->query('page', '1'); $paginator = $this->users->paginate([], $page, 10); return $this->view('users::Admin.index', [ 'title' => trans('common.users'), 'paginator' => $paginator, ]); } public function create(): Response { return $this->view('users::Admin.form', [ 'title' => trans('common.create_user'), 'user' => null, 'roles' => $this->roles->all(), ]); } public function store(Request $request): Response { $data = (new StoreUserRequest())->handle($request); $roles = (array) ($data['roles'] ?? []); unset($data['roles'], $data['password_confirmation']); $user = $this->users->create($data, array_map('intval', $roles)); return $this->redirect(route('admin.users.index')) ->with('_success', trans('common.saved')); } public function edit(int $id): Response { return $this->view('users::Admin.form', [ 'title' => trans('common.edit_user'), 'user' => $this->users->find($id), 'roles' => $this->roles->all(), ]); } public function update(Request $request, int $id): Response { $data = (new UpdateUserRequest())->forUser($id)->handle($request); $roles = isset($data['roles']) ? (array) $data['roles'] : null; unset($data['roles'], $data['password_confirmation']); $this->users->update($id, $data, $roles === null ? null : array_map('intval', $roles)); return $this->redirect(route('admin.users.index')) ->with('_success', trans('common.saved')); } public function destroy(int $id): Response { $this->users->delete($id); return $this->redirect(route('admin.users.index')) ->with('_success', trans('common.deleted')); } } 